<script setup>
import { getFileDetail } from '@/services/knowledge'
import { renderAsync } from 'docx-preview'
const props = defineProps({
  fileType: {
    type: String,
    default: ''
  },
  fileId: {
    type: String,
    default: ''
  }
})

const textList = ref(['txt', 'html', 'htm', 'md', 'json', 'jsonl', 'xml']) //  'epub', 'mobi',
const blobList = ['pdf', 'docx', 'pptx']

const fileContent = ref('')
const docContainer = ref(null)
const loading = ref(false)
function getFileContent() {
  loading.value = true
  getFileDetail(props.fileId, textList.value.includes(props.fileType) ? '' : 'blob')
    .then((res) => {
      console.log('res', res)
      if (textList.value.includes(props.fileType)) {
        fileContent.value = res
      } else if (blobList.includes(props.fileType)) {
        if (props.fileType === 'docx') {
          const blob = new Blob([res], {
            type: 'application/msword;charset=utf-8'
          })
          setTimeout(async () => {
            await renderAsync(blob, docContainer.value)
          }, 100)
        } else if (props.fileType === 'pdf') {
          const blob = new Blob([res], {
            type: 'application/pdf'
          })
          fileContent.value = window.URL.createObjectURL(blob)
        }
      }
    })
    .finally(() => {
      loading.value = false
    })
}

// const emits = defineEmits(['close'])
// function close() {
//   emits('close')
// }

onMounted(() => {
  getFileContent()
})
</script>
<template>
  <div class="text-center" v-if="loading">
    <ProgressSpinner />
  </div>
  <div v-else class="h-full w-full">
    <div v-if="textList.includes(fileType)" class="h-full overflow-auto">
      <pre class="text-left">{{ fileContent }}</pre>
    </div>
    <div v-if="fileType === 'pdf'" class="h-full">
      <iframe :src="fileContent" frameborder="0" width="100%" height="100%"></iframe>
    </div>
    <div v-if="fileType === 'docx'" class="h-full overflow-auto">
      <div ref="docContainer"></div>
    </div>
  </div>
  <!-- <div class="mt-4 flex justify-end">
    <Button :label="$t('lang.close')" @click="close"></Button>
  </div> -->
</template>
